INSERT INTO "dynasty_groups" ("id","name","alt_names","scope","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","note") VALUES ('bei-chao','北朝','[]','cn',420,1,NULL,'year',581,12,NULL,'month',5040,6983,'420–581年北朝（北魏、东魏、西魏、北齐、北周）。');
INSERT INTO "dynasty_groups" ("id","name","alt_names","scope","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","note") VALUES ('nan-chao','南朝','[]','cn',420,1,NULL,'year',589,12,NULL,'month',5040,7079,'420–589年南朝（刘宋、南齐、南梁、南陈及江陵西梁）。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chen-nan','南陈','["陈"]',NULL,NULL,'cn','east_asia',557,1,NULL,'year',589,1,NULL,'year',6684,7068,'ochre',NULL,'nan-chao','陈霸先557年代梁建陈，都建康；文帝、宣帝时期整顿江南并一度收复淮南。北周灭北齐后陈朝独处江南，589年隋军攻陷建康，陈亡并结束南北朝。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-houjing','汉','["汉","侯汉","大汉"]',NULL,NULL,'cn','east_asia',552,1,NULL,'month',552,5,NULL,'month',6624,6628,'ochre',NULL,'nan-chao','侯景原为东魏将领，547年归附梁，548年在寿阳起兵，549年攻陷建康并控制梁廷。552年初迫使萧栋禅位，在建康称帝、国号汉；同年败于王僧辩、陈霸先，逃亡途中被杀，政权结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-nan','南梁','["梁","萧梁"]',NULL,NULL,'cn','east_asia',502,1,NULL,'year',557,1,NULL,'year',6024,6684,'ochre',NULL,'nan-chao','萧衍原为南齐雍州刺史，501年起兵攻入建康，502年取代南齐建梁。前期推行宽政并崇佛，梁朝文化繁盛。548年侯景起兵，549年攻陷建康，梁武帝被困而死；宗室割据内战延续至557年陈霸先受禅，江陵萧氏政权另以西梁名义延续。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-bei','北齐','["齐","高齐"]',NULL,NULL,'cn','east_asia',550,1,NULL,'year',577,1,NULL,'year',6600,6924,'ochre',NULL,'bei-chao','高洋550年取代东魏建齐，都邺；初期整军建制，后期及继位诸帝时朝政渐乱。北周武帝于577年攻灭北齐，北方归于北周。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-nan','南齐','["齐","萧齐"]',NULL,NULL,'cn','east_asia',479,1,NULL,'year',502,1,NULL,'year',5748,6024,'ochre',NULL,'nan-chao','萧道成479年受禅建齐，都建康；齐武帝时期政治与文化较为兴盛。此后宗室争位、皇帝更迭频繁，萧鸾一支大规模诛杀高帝和武帝后裔，最终于502年被萧衍取代。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-liu','刘宋','["宋","南朝宋"]',NULL,NULL,'cn','east_asia',420,7,NULL,'year',479,1,NULL,'year',5046,5748,'ochre',NULL,'nan-chao','刘裕420年取代东晋建国，都建康；文帝时期一度出现“元嘉之治”，后因宗室内乱与权臣兴起而衰弱。479年萧道成受禅，刘宋亡、南齐建立。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-east','东魏','["魏"]','拓跋鲜卑',NULL,'cn','east_asia',534,11,NULL,'year',550,2,NULL,'month',6418,6601,'ochre',NULL,'bei-chao','高欢于532年控制北魏朝政；534年孝武帝西奔长安，高欢另立元善见、迁都邺，东魏由此建立。皇帝长期受高氏控制，550年高欢之子高洋受禅建北齐，东魏结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-north','{"default":"北魏","periods":[{"name":"代","start":{"year":386,"month":1,"confidence":"year"},"end":{"year":386,"month":6,"confidence":"approximate_month"}},{"name":"魏","start":{"year":386,"month":6,"confidence":"approximate_month"},"end":{"year":535,"month":2,"confidence":"month"}}]}','["魏","北魏","拓跋魏"]','拓跋鲜卑',NULL,'cn','east_asia',386,1,NULL,'year',535,2,NULL,'month',4632,6421,'ochre',NULL,'bei-chao','拓跋珪386年重建代国并改称魏，439年太武帝灭北凉、统一北方。孝文帝迁都洛阳并推行制度与风俗改革；六镇之乱后政权衰弱，534年分裂为东魏、西魏，535年北魏名义终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-west','西魏','["魏"]','拓跋鲜卑',NULL,'cn','east_asia',535,2,NULL,'year',557,2,NULL,'month',6421,6685,'ochre',NULL,'bei-chao','宇文泰于535年在长安拥立元宝炬，建立西魏，与高欢控制的东魏对峙。西魏朝廷由宇文泰掌握，557年宇文觉受禅建北周，西魏结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-bei','北周','["周","宇文周"]','宇文鲜卑',NULL,'cn','east_asia',557,2,NULL,'month',581,3,NULL,'month',6685,6974,'ochre',NULL,'bei-chao','宇文觉557年受禅建周，都长安，实际政权先受宇文护控制。武帝亲政后整军并于577年灭北齐、统一北方；581年杨坚受禅建隋，北周结束。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-baxian','陈霸先','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','吴兴长城人，早年任地方军职，参与平定交州叛乱。侯景之乱中于550年在始兴起兵，551年与王僧辩会师，552年收复建康。555年因王僧辩接受北齐扶立的萧渊明而袭杀王僧辩，改立萧方智；击退北齐后，557年受禅建立陈朝，都建康，559年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈霸先"}]','武皇帝','高祖','陈武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-bozong','陈伯宗','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈蒨之子，566年即位，在位至568年。因年幼且政局受叔父陈顼掌握，旋被废为临海王；陈顼继位后陈朝进入新的统治阶段。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈伯宗"}]',NULL,NULL,'陈废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-qian','陈蒨','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈霸先之侄，陈朝第二帝，559—566年在位。其间整顿政务、恢复江南生产并多次击退北齐，陈朝国势较建国初有所恢复。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈蒨"}]','文皇帝',NULL,'陈文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-qingzhi','陈庆之','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','南朝梁将领，字子云，义兴国山人。梁武帝时率军护送北魏宗室元颢北上，曾连克洛阳周边城邑；元颢败亡后退兵，部众在河洛地区溃散，陈庆之辗转返回南梁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈庆之"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-shubao','陈叔宝','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈顼长子，582—589年在位，是陈朝末帝。北周灭北齐后，陈朝独处江南而未能整军；589年隋军渡江攻陷建康，陈亡，南北朝结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈叔宝"}]',NULL,NULL,'陈后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-xu','陈顼','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陈霸先之侄、陈蒨之弟，568—582年在位。整顿军政并趁北齐衰乱发动北伐，一度收复淮南；晚年继承安排未稳，死后由子陈叔宝即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈顼"}]','宣皇帝',NULL,'陈宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('erzhu-rong','尔朱荣','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','北魏末年将领、权臣，契胡尔朱部首领。六镇起义后拥兵入洛阳，镇压葛荣并掌控朝政，河阴之变中屠杀朝臣；530年入宫被孝庄帝元子攸伏杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/尔朱荣"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-taihou','冯太后','wei-north','[]',NULL,NULL,442,1,NULL,'year',490,1,NULL,'year','["太后","政治家"]','北魏文明太后，献文帝、孝文帝朝两度临朝，推动改革；她推动均田、俸禄等制度变革，并支持孝文帝迁都洛阳及汉化改革。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯太后"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-heng','高恒','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高纬之子，577年北齐覆亡之际被立为帝，在位至578年。其即位时北齐领土已尽失，出逃途中被北周军俘获，北齐宗室政权彻底终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高恒"}]',NULL,NULL,'齐幼主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-wei','高纬','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高湛长子，569—577年在位，史称后主。朝政受宠臣与宫廷势力影响，北周武帝于577年攻灭北齐；高纬被俘后仍被处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高纬"}]',NULL,NULL,'齐后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yan','高演','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高欢第六子、高洋同母弟，560年废黜高殷后即位，史称孝昭帝，在位至565年。勤于政事并整顿朝纲，病重后传位弟高湛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐孝昭帝"}]','孝昭皇帝',NULL,'齐孝昭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yang','高洋','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高欢次子、高澄之弟。高欢于534年拥立元善见，掌握东魏军政；高澄继承父权后于549年被刺杀，高洋接掌其势力。550年迫使东魏孝静帝禅位，建立齐朝，都邺。在位初期整顿军政并对外征战，晚年酗酒与杀戮加剧，559年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐文宣帝"},{"label":"人物生平与建国经历","url":"https://zh.wikipedia.org/wiki/高洋"}]','文宣皇帝',NULL,'齐文宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yin','高殷','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高洋长子，559年继位，史称废帝，在位至560年。年少而有意亲政，被叔父高演废黜并幽禁，随后遇害；北齐皇位转入高欢另一支。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐废帝"}]',NULL,NULL,'齐废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-zhan','高湛','qi-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高欢第九子、高洋与高演之弟，565年继位，在位至569年，随后传位太子高纬而以太上皇身份继续影响政局。其统治使北齐朝政和边防进一步衰弱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐武成帝"}]','武成皇帝',NULL,'齐武成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hou-jing','侯景','han-houjing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["将领"]','原为东魏将领，统辖河南诸地。高欢死后因与高澄不合，547年先后联络西魏、梁，梁武帝接纳其归附；梁与东魏议和又使侯景担心被交还，548年在寿阳起兵。549年攻陷建康，控制梁帝，552年称帝、国号汉；同年败于王僧辩、陈霸先，逃亡途中被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/侯景"}]',NULL,NULL,'汉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-taihou','胡太后','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,528,5,17,'day','["太后","政治家"]','北魏灵太后，孝明帝元诩生母，两度临朝。528年与郑俨、徐纥合谋毒杀孝明帝，先立孝明帝之女，旋改立幼主元钊；尔朱荣进军洛阳后，在河阴将她与元钊沉入黄河。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡太后"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-jun','刘骏','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘义隆第三子，平定刘劭之乱后于453年即位，在位至464年。即位初稳定朝局并拓展疆土，后期频繁征役、严酷治宗室，刘宋政治由此转趋动荡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘骏"}]','孝武皇帝','世祖','宋孝武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-shao','刘劭','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘义隆长子，453年弑父后短暂即位，旋被弟弟刘骏起兵击败并处死。其弑父篡位引发刘宋宗室内战，谥号元凶。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘劭"}]',NULL,NULL,'宋元凶','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yifu','刘义符','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘裕长子，刘宋第二帝，422—424年在位。即位后年少失政，徐羡之、傅亮等废黜并杀害他，改立其弟刘义隆。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘义符"}]',NULL,NULL,'宋少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yilong','刘义隆','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘裕第三子，424—453年在位，是刘宋在位较久的皇帝。其前期整顿吏治、发展经济，史称“元嘉之治”；后期北伐失利，终被太子刘劭弑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘义隆"}]','文皇帝','太祖','宋文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yu-fei','刘昱','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘彧长子，472—477年在位，年幼即位后逐渐亲政，行为失度并滥杀大臣。萧道成掌握朝政后将其杀害，另立刘准。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘昱"}]',NULL,NULL,'宋后废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yu-song','刘彧','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘义隆之弟，465—472年在位，政变中被拥立为帝。为巩固权力大规模诛杀宗室，刘宋统治集团进一步削弱；死后子刘昱继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘彧"}]','明皇帝','太宗','宋明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhun','刘准','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘彧第三子，477—479年在位，幼年被萧道成立为帝，政权实权已归萧氏。479年禅位于萧道成，刘宋亡，南齐建立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘准"}]','顺皇帝',NULL,'宋顺帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ziye','刘子业','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘骏长子，464—465年在位，年少即位后诛杀宗室与大臣，统治迅速失去支持。寿命短促，在宫廷政变中被叔父刘彧一方杀死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘子业"}]',NULL,NULL,'宋前废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-gui','拓跋珪','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','代王拓跋什翼犍之孙。376年代被前秦所灭后，依托独孤、贺兰等部保存力量；前秦衰乱时，于386年恢复代国，随后改国号魏。通过战争整合北方部众，398年迁都平城并称帝。此后推进官制及农业经营，409年被子拓跋绍杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏道武帝"},{"label":"《魏书》卷二·太祖纪","url":"https://wk.100ke.info/wiki/魏書/卷2"},{"label":"代（十六国）","url":"https://zh.wikipedia.org/wiki/代_(十六国)"},{"label":"人物生平与建国经历","url":"https://zh.wikipedia.org/wiki/拓跋珪"}]','道武皇帝','太祖','魏道武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-hong','拓跋弘','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋浚长子，465—471年在位，史称献文帝。即位时年幼，冯太后临朝；后来传位于年幼的拓跋宏，仍参与朝政，最终去世于权力冲突之中。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏献文帝"}]','献文皇帝',NULL,'魏献文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-jun','拓跋浚','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋晃之子，452—465年在位，史称文成帝。即位后重建朝廷秩序、缓和太武帝晚年的政治震荡，并恢复佛教活动；其子拓跋弘继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏文成帝"}]','文成皇帝','高宗','魏文成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-kuo','拓跋廓','wei-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宝炬第四子，原姓元，554年由宇文泰拥立，史称西魏恭帝，在位至557年。宇文觉受禅建北周后，西魏灭亡；元廓随后被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏恭帝"}]','恭帝',NULL,'魏恭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-si','拓跋嗣','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋珪之子，409年继位，在位至423年，后尊为明元帝。其间巩固平城政权、向黄河流域扩张，并为子拓跋焘继续统一北方打下基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏明元帝"}]','明元皇帝','太宗','魏明元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-tao','拓跋焘','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋嗣之子，424—452年在位，史称太武帝。通过长期征战先后灭夏、北燕、北凉，439年统一北方；晚年因宫廷冲突被宦官宗爱弑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏太武帝"}]','太武皇帝','世祖','魏太武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuoba-yu','拓跋余','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','太武帝拓跋焘之子，452年在宗爱弑帝后被拥立，在位仅数月即遇害。其死引发宫廷清洗，文成帝拓跋浚随后即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元余"}]',NULL,NULL,'魏南安王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-baojuan','萧宝卷','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧鸾之子，499—501年在位。其猜忌诛杀大臣引发各地叛乱，雍州刺史萧衍起兵攻入建康，萧宝卷被杀，南齐政权随之崩解。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧宝卷"}]',NULL,NULL,'东昏侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-baorong','萧宝融','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧鸾之子，501年由萧衍拥立于江陵，次年迁至建康并禅位。502年萧衍受禅建梁，南齐结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧宝融"}]','和帝',NULL,'齐和帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-daocheng','萧道成','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧承之之子，历仕刘宋，472年任右卫将军，474年平定刘休范叛乱后势力上升。477年刘昱被杀，萧道成拥立刘准并掌握朝政；478年击败袁粲、沈攸之等反对势力，479年受禅建立齐朝，以建康为都。在位时裁减冗费，482年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧道成"}]','高皇帝','太祖','齐高帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-dong','萧栋','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧统之孙、豫章王萧欢之子，551年被侯景从禁中拥立为帝。侯景旋即废其为淮阴王并囚禁；梁宗室随后继续拥兵争位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧栋"}]',NULL,NULL,'梁废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-fangzhi','萧方智','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧绎之侄，555年在江陵一度受西魏扶立，后由陈霸先迎立于建康，在位至557年。陈霸先受禅建陈，南梁正式结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧方智"}]','敬帝',NULL,'梁敬帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-gang','萧纲','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧衍第三子，549年侯景攻陷建康后被拥立，在位至551年。侯景为巩固控制废黜并杀害他，梁廷此后沦为侯景操纵的傀儡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧纲"}]','简文帝',NULL,'梁简文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-luan','萧鸾','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','齐高帝侄、齐武帝堂弟，494年废杀萧昭文后即位，在位至498年。为巩固旁支统治大肆诛戮高帝、武帝子孙，造成南齐宗室凋敝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧鸾"}]','明皇帝','高宗','齐明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-yan','萧衍','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧顺之之子，南齐宗室将领，曾任雍州刺史。500年兄萧懿被齐帝萧宝卷杀害，萧衍在襄阳组织军队，501年东下攻取建康。拥立萧宝融后掌握齐廷，502年受禅建立梁朝。前期整顿政治并崇尚佛教，晚年侯景之乱攻陷建康，549年被困台城而死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧衍"}]','武皇帝','高祖','梁武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-yi','萧绎','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧衍第七子，先据江陵与侯景及各地梁军相持，552年称帝，在位至555年。西魏军攻陷江陵后将其杀害，梁朝西部核心由此覆灭。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧绎"}]','孝元皇帝',NULL,'梁元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-ze','萧赜','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧道成长子，482—493年在位。其年号“永明”时期朝政相对安定、文化兴盛，但晚年未妥善安排继承，身后引发皇位争夺。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧赜"}]','武皇帝','世祖','齐武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-zhaowen','萧昭文','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧昭业之弟，494年被萧鸾拥立，在位仅数月即遭废黜并被杀。其短暂即位反映南齐宗室权力已由萧鸾掌控。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧昭文"}]',NULL,NULL,'齐海陵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-zhaoye','萧昭业','qi-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','萧赜之孙、文惠太子萧长懋之子，494年短暂在位。萧鸾以其荒怠为由废杀，另立其弟萧昭文，南齐皇位由此落入旁支。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧昭业"}]',NULL,NULL,'齐郁林王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-jian','杨坚','sui','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝","政治家"]','北周将领杨忠之子，女儿杨丽华为周宣帝皇后。580年宣帝去世，刘昉、郑译等引他入朝辅佐幼主，杨坚掌握中央军政；击败尉迟迥等反对势力后，581年受周静帝禅让建立隋朝。迁都大兴，589年灭陈统一南北，整顿官制、赋役与律令，604年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨坚"}]','文皇帝','高祖',NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-bao-ju','元宝炬','wei-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元愉之子、北魏孝文帝之孙。534年随孝武帝元修西赴关中；535年元修被宇文泰杀害，元宝炬获拥立为帝，西魏以长安为都。朝廷军政实权由宇文泰掌握，与高欢所控制的东魏对峙，元宝炬于551年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元宝炬"}]','文皇帝',NULL,'魏文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-hong','元宏','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','拓跋弘之子，471—499年在位，史称孝文帝。亲政后迁都洛阳，推行改汉姓、改服制与官制等改革，推动北魏统治中心及鲜卑贵族深度转型。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝文帝"}]','孝文皇帝','高祖','魏孝文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-ke','元恪','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宏之子，499—515年在位，史称宣武帝。延续洛阳朝廷与对南朝的军事行动，晚年外戚、高门势力上升；死后幼子元诩继位，胡太后临朝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏宣武帝"}]','宣武皇帝',NULL,'魏宣武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-lang','元朗','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','北魏宗室安定王元朗，531年由高欢拥立，在位至532年。高欢击败尔朱氏后改立孝文帝之孙元修，元朗被废；北魏政权此后由高欢掌控。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元朗"}]','节闵帝',NULL,'魏节闵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-qin','元钦','wei-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宝炬长子，551年继位，史称西魏废帝，在位至554年。试图摆脱宇文泰控制并谋杀其亲信，事泄后被废杀，弟元廓继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元钦"}]',NULL,NULL,'魏废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shan-jian','元善见','wei-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元亶之子、孝文帝曾孙。534年北魏孝武帝元修与高欢决裂，西赴关中；高欢另立元善见，迁都邺，形成东魏。元善见在位时军政实权由高欢及高澄、高洋相继掌握，550年禅位于高洋，次年被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝静帝"},{"label":"人物生平与建国经历","url":"https://zh.wikipedia.org/wiki/元善见"}]','孝静皇帝',NULL,'魏孝静帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shi-xiaoming-daughter','元氏','wei-north','["元姑娘","孝明帝之女","女帝元氏"]',NULL,NULL,528,1,NULL,'year',NULL,NULL,NULL,NULL,'["皇帝"]','孝明帝元诩与潘充华之女，姓名失载。528年孝明帝死后，胡太后以皇子名义立她为帝，旋即承认其为皇女，改立临洮王世子元钊；此后事迹失载。','[{"label":"维基百科：孝明帝之女","url":"https://zh.wikipedia.org/wiki/元氏_(魏孝明帝女)"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]',NULL,NULL,'女帝元氏','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-xiu','元修','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元宏之孙，532年由高欢拥立，史称孝武帝。534年与高欢决裂后西奔长安投宇文泰；北魏由此分为东魏、西魏，元修次年被宇文泰杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝武帝"}]','孝武皇帝',NULL,'魏孝武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-xu','元诩','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元恪之子，515—528年在位，史称孝明帝。即位后由生母胡太后临朝，成年后试图收回权力；528年胡太后与郑俨、徐纥合谋将其毒杀，尔朱荣借机发动河阴之变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝明帝"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]','孝明皇帝',NULL,'魏孝明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-ye','元晔','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','北魏宗室长广王，尔朱世隆等人在530年拥立为帝，在位至531年。高欢起兵反尔朱氏后，元晔被废并遭软禁，随后由元朗被拥立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元晔"}]',NULL,NULL,'魏长广王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-zhao','元钊','wei-north','["北魏幼主","魏幼主"]',NULL,NULL,526,1,NULL,'year',528,5,17,'day','["皇帝"]','临洮王元宝晖之子、孝文帝元宏曾孙。528年孝明帝死后，胡太后先立皇女，旋改立年幼的元钊，继续临朝。尔朱荣拥立元子攸并进军洛阳，同年在河阴将元钊与胡太后沉入黄河。','[{"label":"维基百科：元钊","url":"https://zh.wikipedia.org/wiki/元钊"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷13·皇后列传","url":"https://zh.wikisource.org/zh-hans/魏書/卷13"}]',NULL,NULL,'魏幼主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-zi-you','元子攸','wei-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','元勰之子，528年在尔朱荣扶立下即位，史称孝庄帝。亲政后于530年诛杀尔朱荣，却很快被尔朱氏势力拘捕并杀害，北魏朝廷进一步失控。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏孝庄帝"},{"label":"《资治通鉴》卷152","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷152"},{"label":"《魏书》卷10·孝庄纪","url":"https://zh.wikisource.org/zh-hans/魏書/卷10"}]','孝庄皇帝',NULL,'魏孝庄帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-jue','宇文觉','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文泰第三子。宇文泰自535年西魏建立后掌握关中军政，556年去世时由宇文觉承袭爵位，宇文护主持政务。557年受西魏恭帝禅让，以天王为号建立周朝。宇文觉试图除掉宇文护、收回权力，同年被废杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周孝闵帝"},{"label":"人物生平与建国经历","url":"https://zh.wikipedia.org/wiki/宇文觉"}]','孝闵帝',NULL,'周孝闵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yan','宇文衍','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文赟之子，579年由父亲禅位即位，史称静帝，在位至581年。年幼而受外戚杨坚控制，581年杨坚受禅建立隋朝，北周灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周静帝"}]','静帝',NULL,'周静帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yong','宇文邕','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文泰第四子，560年继位，史称武帝，在位至578年。亲政后诛杀宇文护，整顿军政并于577年灭北齐，统一北方；筹备南征期间病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周武帝"}]','武皇帝',NULL,'周武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yu','宇文毓','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文泰长子，557年继位，史称明帝，在位至560年。朝政仍由宇文护主导，宇文毓试图削弱其权力，后被宇文护派人毒杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周明帝"}]','明皇帝',NULL,'周明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuwen-yun','宇文赟','zhou-bei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','宇文邕长子，578年继位，史称宣帝，在位至579年。即位后迅速传位年幼的宇文阐，自称天元皇帝，仍操控朝政；其死后杨坚掌握辅政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周宣帝"}]','宣皇帝',NULL,'周宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-lihua','张丽华','chen-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,589,1,NULL,'year','["后妃","政治家"]','南朝陈后主贵妃，出身寒微，入宫后受陈叔宝宠爱并生育皇子。隋军攻破建康时，她与后主藏入井中后被俘杀害；正史未载其确切生年，后世亦有不同死因叙述。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张丽华"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zu-chongzhi','祖冲之','song-liu','[]',NULL,NULL,429,1,NULL,'year',500,1,NULL,'year','["科学家"]','南朝宋、齐时期数学家、天文学家，字文远。将圆周率精算至小数点后七位，制定《大明历》，并研究机械制造；其子祖暅之亦以数学著称。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/祖冲之"}]',NULL,NULL,NULL,'[]');
