INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('chen-qingzhi-luoyang','白袍军入洛','battle','point','year',NULL,NULL,'528年，陈庆之率七千白袍军入洛阳',528,12,NULL,6347,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'陈庆之率七千白袍军护送元颢入洛，威震北魏。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('he-yin-massacre','河阴之变','politics','point','month',NULL,NULL,'528年，尔朱荣在河阴杀害胡太后、幼主元钊并屠杀百官。史书记于农历四月；据元钊条目换算为公历5月，事件整体保留月精度。',528,5,NULL,6340,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'尔朱荣在河阴将胡太后与幼主元钊沉入黄河，随后屠杀北魏王公朝臣两千余人。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('houjing-rebellion','侯景之乱','politics','span',NULL,'year','year','548–552年，侯景叛梁，陷建康',NULL,NULL,NULL,NULL,548,1,NULL,6576,552,1,NULL,6624,'侯景叛梁，攻陷建康，梁武帝饿死台城，江南凋敝。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('tuoba-gui-change-country-name','拓跋珪改国号为魏','politics','point','year',NULL,NULL,'登国元年夏四月（农历，386年）；《魏书·太祖纪》原文作“改称魏王”。因未核得可靠的公历月日换算，事件按年精度记载。',386,12,NULL,4643,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'前秦灭代后，拓跋氏政权一度中断。淝水之战后前秦瓦解，什翼犍之孙拓跋珪于386年在牛川复立代国、即代王位；同年夏四月，他改称魏王，政权由“代”转为“魏”，后世称北魏。此后拓跋珪逐步整合北方部众，为北魏扩张奠定基础。',NULL,NULL,'[]');
